<script setup lang="ts">
import segments from '~/data/rehearsal.json'
import demos from '~/data/demos.json'
useHead({ title: 'Live demo rehearsal · The AI Toolkit' })
const copied = ref('')
const error = ref(false)
const findDemo = (slug?: string) => demos.find(demo => demo.slug === slug)
async function copy(id: string, prompt: string) { try { await navigator.clipboard.writeText(prompt); copied.value = id; error.value = false } catch { error.value = true } }
</script>
<template><main id="main" class="wrap directory"><div class="page-intro"><NuxtLink to="/toolkit" class="back-link">← Back to the toolkit</NuxtLink><p class="eyebrow">Presenter rehearsal / 60 minutes</p><h1 class="display gradient-title">A day at Safi.</h1><p class="lead">One business. Sales, marketing, documents, stock and a tool to reuse. A local workflow and time to try it yourself.</p></div>
<div class="directory-note"><b>Before the room</b><p>Open ChatGPT, the prepared notebook, Codex in an empty demo folder, this guide, the slides and the offline calculator. Download the pack before leaving reliable Wi-Fi. Clear welcome dialogs and test the projector, text size and hotspot. Use the supplied notes and hide unrelated chats or notifications.</p><p>Allow 30 seconds for the opening generation, 45 seconds for a later response. One recovery attempt, then the prepared fallback. If behind, cut chart generation and the print-button enhancement. Protect the participant exercises and the 10:20 finish.</p><a class="text-link" href="/resources/dada-hub-demo-kit.zip" download>Download the PDF rehearsal & fallback pack ↗</a></div>
<nav class="rehearsal-toc" aria-label="Rehearsal sections"><a v-for="segment in segments" :key="segment.id" :href="`#${segment.id}`">{{ segment.time }} · {{ segment.title }}</a></nav>
<section v-for="segment in segments" :id="segment.id" :key="segment.id" class="rehearsal-segment"><p class="eyebrow">{{ segment.time }} EAT · {{ segment.duration }}</p><h2>{{ segment.title }}</h2><blockquote>“{{ segment.say }}”</blockquote><div class="rehearsal-columns"><div><h3>Do this</h3><ol><li v-for="step in segment.steps" :key="step">{{ step }}</li></ol></div><div><h3>The pass condition</h3><p>{{ segment.pass }}</p><p class="fallback-label">If it fails, say and do this</p><p>{{ segment.fallback }}</p><NuxtLink v-if="segment.demo" class="text-link" :to="`/demos/${segment.demo}`">Open the demo & sample ↗</NuxtLink><NuxtLink v-if="segment.id === 'workflow' || segment.id === 'your-workflow'" class="text-link" to="/workflow">Open the workflow lab ↗</NuxtLink></div></div>
<details v-if="segment.prompt || segment.demo"><summary>Exact copy-and-paste prompt</summary><div class="prompt-toolbar"><span>Use the complete prompt</span><button class="copy-button" @click="copy(segment.id, segment.prompt || findDemo(segment.demo)?.prompt || '')">{{ copied === segment.id ? 'Copied ✓' : 'Copy prompt' }}</button></div><pre class="prompt-text">{{ segment.prompt || findDemo(segment.demo)?.prompt }}</pre><template v-if="segment.demo"><h3>Follow-up</h3><pre class="prompt-text">{{ findDemo(segment.demo)?.followup }}</pre><template v-if="findDemo(segment.demo)?.marketing"><h3>Part two: weekly marketing</h3><DemoPrompt :text="findDemo(segment.demo)!.marketing!.prompt" label="Weekly marketing prompt" /></template></template></details></section><p v-if="error" role="status">Clipboard unavailable. Select the prompt and copy it manually.</p></main></template>
